<script setup>
import UiMoneyInput from '~/components/ui/MoneyInput.vue'
import { money, paymentMethodLabel, dateLabel, timeLabel, initials } from '#shared/utils/format.js'
const props=defineProps({ id: String, mobile: Boolean })
const {user,canManageOrders,canAssign,isOwner,isLocationAdmin}=useAuth();const {toast,error:formatError}=useFeedback()
const {data:order,refresh,error}=await useFetch(`/api/orders/${props.id}`)
const {countdown,remainingSeconds:treatmentRemaining,canComplete:canFinishTreatment}=useTreatmentCountdown(()=>order.value?.treatment,refresh)
const {data:locations}=await useFetch(isLocationAdmin.value?'/api/orders/options':'/api/locations',{default:()=>[],immediate:!props.mobile})
const availability=ref([]);const locationId=ref('');const therapistId=ref('');const busy=ref(false);const message=ref('');const reason=ref('');const reasonAction=ref('');const paymentOpen=ref(false)
const issuedJobLink=ref(null)
const payment=reactive({amount:0,paymentMethod:'CASH',paymentReference:''})
const isTherapist=computed(()=>user.value?.role==='THERAPIST')
const nextAction=computed(()=>order.value?.assignment?.isActive?({ASSIGNED_THERAPIST:['accept','Terima job'],ACCEPTED:['on-the-way','Mulai perjalanan'],ON_THE_WAY:['arrived','Saya sudah tiba'],ARRIVED:['start','Mulai treatment'],IN_PROGRESS:['complete','Selesaikan treatment']}[order.value?.orderStatus]):null)
const remaining=computed(()=>order.value?.remainingAmount!==undefined?Number(order.value.remainingAmount):Number(order.value?.total || 0)-(order.value?.payments || []).filter(p=>p.status==='SUCCESS').reduce((n,p)=>n+Number(p.amount),0))
async function loadAvailability(){if(canAssign.value&&order.value?.locationId&&['ASSIGNED_LOCATION','ASSIGNED_THERAPIST','THERAPIST_REJECTED','NO_THERAPIST_AVAILABLE','ACCEPTED'].includes(order.value.orderStatus)){try{availability.value=await $fetch(`/api/orders/${props.id}/availability`)}catch(e){message.value=formatError(e)}}}
await loadAvailability();usePolling(async()=>{await refresh();await loadAvailability()})
async function action(name,body={}){if(name==='complete'&&!canFinishTreatment.value)return;busy.value=true;message.value='';try{const result=await $fetch(`/api/orders/${props.id}/${name}`,{method:'POST',body});if(name==='assign-therapist')issuedJobLink.value=result.jobLink;toast('Order berhasil diperbarui');reasonAction.value='';await refresh();await loadAvailability()}catch(e){message.value=formatError(e)}finally{busy.value=false}}
async function jobLinkIssued(link){issuedJobLink.value=link;await refresh()}
function openPayment(){payment.amount=remaining.value;paymentOpen.value=true}
async function pay(){busy.value=true;message.value='';try{await $fetch('/api/payments',{method:'POST',body:{...payment,amount:Number(payment.amount),orderId:order.value.id}});paymentOpen.value=false;toast('Pembayaran berhasil dicatat');await refresh()}catch(e){message.value=formatError(e)}finally{busy.value=false}}
</script><template><div v-if="order"><LayoutPageHeader :title="mobile?'Detail job':order.orderNumber" :description="dateLabel(order.bookingDate)+' · '+order.bookingTime.slice(0,5)+' · '+order.timezone" eyebrow="BOOKING DETAILS"><UiBadge :status="order.orderStatus" /><UiButton v-if="canManageOrders&&['NEW','CONFIRMED'].includes(order.orderStatus)&&!order.revenueShare?.frozen&&order.payments.length===0&&order.paymentStatus==='UNPAID'" :to="'/orders/'+id+'/edit'" variant="secondary"><UiIcon name="edit" :size="16" />Edit</UiButton><UiButton :to="mobile?'/therapist':'/orders'" variant="ghost"><UiIcon name="back" :size="16" />Kembali</UiButton></LayoutPageHeader><p v-if="message" class="error-message" role="alert">{{ message }}</p><div :class="mobile?'space-y-5':'detail-grid'"><div class="space-y-5"><section class="panel form-panel"><div class="panel-heading no-pad"><h2>Informasi customer</h2><span class="subtle-tag">{{ order.source }}</span></div><div class="customer-profile"><span class="avatar large pastel">{{ initials(order.customerName) }}</span><div><h3>{{ order.customerName }}</h3><a :href="'tel:'+order.customerPhone" class="text-link"><UiIcon name="phone" :size="14" />{{ order.customerPhone }}</a></div></div><div class="address-box"><UiIcon name="locations" /><div><strong>Alamat treatment</strong><p>{{ order.addressSnapshot }}</p><small>{{ order.locationName || 'Cabang belum ditetapkan' }}</small></div></div><LocationDirections :latitude="order.latitude" :longitude="order.longitude" :address="order.addressSnapshot" /><p v-if="order.notes" class="note-box">{{ order.notes }}</p></section><section class="panel form-panel"><h2>Treatment</h2><OrderTreatmentCountdown v-if="order.orderStatus==='IN_PROGRESS'" :countdown="countdown" :remaining-seconds="treatmentRemaining" :duration-minutes="order.treatment?.durationMinutes" /><div v-for="item in order.items" :key="item.id" class="treatment-item"><span class="metric-icon green"><UiIcon name="services" /></span><div><strong>{{ item.serviceNameSnapshot }}</strong><small>{{ item.durationMinutes }} menit × {{ item.qty }}</small></div><strong>{{ money(item.subtotal) }}</strong></div><div class="billing-line"><span>Subtotal</span><strong>{{ money(order.subtotal) }}</strong></div><div class="billing-line"><span>Diskon</span><span>− {{ money(order.discount) }}</span></div><div v-if="Number(order.transportFee)>0" class="billing-line"><span>Biaya transport</span><span>{{ money(order.transportFee) }}</span></div><div v-if="Number(order.tax)>0" class="billing-line"><span>Pajak</span><span>{{ money(order.tax) }}</span></div><div class="billing-total"><span>Total tagihan</span><strong>{{ money(order.total) }}</strong></div></section><section v-if="!mobile" class="panel form-panel"><h2>Riwayat assignment</h2><div v-for="a in order.assignments" :key="a.id" class="assignment-history"><span class="avatar">{{ initials(a.therapistName) }}</span><div><strong>{{ a.therapistName }}</strong><small>{{ timeLabel(a.assignedAt) }}</small><p v-if="a.rejectionReason">{{ a.rejectionReason }}</p></div><UiBadge :status="a.responseStatus" /></div><p v-if="!order.assignments.length" class="muted">Therapist belum ditetapkan.</p></section><section class="panel form-panel"><h2>Timeline order</h2><OrderTimeline :logs="order.logs" /></section></div><aside class="space-y-5"><OrderWhatsAppCard v-if="canAssign&&order.assignment?.isActive&&['ASSIGNED_THERAPIST','ACCEPTED','ON_THE_WAY','ARRIVED','IN_PROGRESS'].includes(order.orderStatus)" :order="order" :issued="issuedJobLink" @issued="jobLinkIssued" /><section v-if="isTherapist&&nextAction" class="panel form-panel"><h2>Langkah berikutnya</h2><p class="muted mb-4">Perbarui status agar tim dapat memantau pelayanan Anda.</p><UiButton class="w-full" :loading="busy" :disabled="nextAction[0]==='complete'&&!canFinishTreatment" @click="action(nextAction[0])">{{ nextAction[1] }}<UiIcon name="arrow" :size="17" /></UiButton><UiButton v-if="order.orderStatus==='ASSIGNED_THERAPIST'" variant="ghost" class="w-full" @click="reasonAction='reject';reason=''">Tolak job</UiButton></section><section v-if="!isTherapist" class="panel form-panel"><h2>Dispatch & tindakan</h2><UiButton v-if="canManageOrders&&order.orderStatus==='NEW'" class="w-full" :loading="busy" @click="action('confirm')">Konfirmasi order</UiButton><form v-if="canManageOrders&&['CONFIRMED','ASSIGNED_LOCATION','THERAPIST_REJECTED','NO_THERAPIST_AVAILABLE'].includes(order.orderStatus)" @submit.prevent="action('assign-location',{locationId:Number(locationId)})"><label>Lokasi<select v-model="locationId" aria-label="Lokasi" required><option value="" disabled>Pilih lokasi</option><option v-for="l in (isLocationAdmin?locations?.locations||[]:locations).filter(l=>l.isActive)" :key="l.id" :value="l.id">{{ l.name }}</option></select></label><UiButton type="submit" variant="secondary" class="w-full" :loading="busy">Tetapkan lokasi</UiButton></form><form v-if="canAssign&&['ASSIGNED_LOCATION','ASSIGNED_THERAPIST','THERAPIST_REJECTED','NO_THERAPIST_AVAILABLE','ACCEPTED'].includes(order.orderStatus)" @submit.prevent="action('assign-therapist',{therapistId:Number(therapistId)})"><label>Therapist<select v-model="therapistId" aria-label="Therapist" required><option value="" disabled>Pilih therapist yang tersedia</option><option v-for="t in availability" :key="t.id" :value="t.id" :disabled="!t.available">{{ t.name }} · {{ t.reason }}</option></select></label><UiButton type="submit" class="w-full" :loading="busy">{{ order.assignment?'Alihkan therapist':'Assign therapist' }}</UiButton><p class="form-hint">Ketersediaan dihitung untuk jadwal order ini.</p></form><UiButton v-if="order.orderStatus==='PAID'" class="w-full" :loading="busy" @click="action('close')">Tutup order</UiButton><UiButton v-if="!['CLOSED','PAID','COMPLETED','CANCELLED_BY_ADMIN','CANCELLED_BY_CUSTOMER'].includes(order.orderStatus)" variant="danger" class="w-full mt-4" @click="reasonAction='cancel';reason=''">Batalkan order</UiButton><p v-if="['ON_THE_WAY','ARRIVED','IN_PROGRESS','COMPLETED','CLOSED'].includes(order.orderStatus)" class="muted">Status operasional diperbarui oleh therapist yang ditugaskan.</p></section><section class="panel form-panel"><div class="panel-heading no-pad"><h2>Pembayaran</h2><UiBadge :status="order.paymentStatus" /></div><div class="billing-line"><span>Sisa tagihan</span><strong>{{ money(remaining) }}</strong></div><div v-for="p in order.payments" :key="p.id" class="payment-history"><div><strong>{{ money(p.amount) }}</strong><small>{{ paymentMethodLabel(p.paymentMethod) }} · {{ timeLabel(p.paidAt) }}</small></div><UiBadge :status="p.status" /></div><UiButton v-if="isOwner&&!['CLOSED','PAID','CANCELLED_BY_ADMIN','CANCELLED_BY_CUSTOMER'].includes(order.orderStatus)&&remaining>0" class="w-full mt-4" @click="openPayment">Catat pembayaran</UiButton><p v-if="order.orderStatus==='COMPLETED'&&remaining===0" class="form-hint">Tidak ada tagihan tersisa.</p></section><OrderRevenueShare v-if="isOwner" :share="order.revenueShare" /></aside></div><UiModal :open="!!reasonAction" :title="reasonAction==='reject'?'Tolak job':'Batalkan order'" @close="reasonAction=''"><form @submit.prevent="action(reasonAction,{notes:reason})"><label>Alasan<textarea v-model="reason" required minlength="3" rows="3" /></label><div class="modal-actions"><UiButton variant="secondary" @click="reasonAction=''">Kembali</UiButton><UiButton type="submit" variant="danger" :loading="busy">Konfirmasi</UiButton></div></form></UiModal><UiModal :open="paymentOpen" title="Catat pembayaran" @close="paymentOpen=false"><form @submit.prevent="pay"><label>Jumlah (Rp)<UiMoneyInput v-model="payment.amount" :min="0.01" :max="remaining" required /></label><label>Metode<select v-model="payment.paymentMethod"><option v-for="m in ['CASH','BANK_TRANSFER','QRIS','CARD','ONLINE_PAYMENT']" :key="m" :value="m">{{ paymentMethodLabel(m) }}</option></select></label><label>Referensi<input v-model="payment.paymentReference" placeholder="Nomor transfer / transaksi (opsional)" /></label><p v-if="message" class="error-message">{{ message }}</p><div class="modal-actions"><UiButton variant="secondary" @click="paymentOpen=false">Batal</UiButton><UiButton type="submit" :loading="busy">Simpan pembayaran</UiButton></div></form></UiModal></div><UiEmptyState v-else title="Order tidak ditemukan" :message="error?.data?.statusMessage || 'Anda tidak memiliki akses ke order ini.'" /></template>